WITH dim_totals AS (SELECT p.city, e.status, COUNT(*) AS num_rows, MIN(e.amount) AS min_amount, GROUPING_ID() AS gid FROM orders e LEFT JOIN customers p ON e.customer_id = p.id GROUP BY CUBE (p.city, e.status)) SELECT status, min_amount, gid, CASE WHEN status RLIKE '^(RETURNED|SHIPPED)$' THEN 'GROUP_B' WHEN status RLIKE '^(COMPLETED|PENDING)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS status_zone FROM dim_totals
